PRAGMA foreign_keys = ON;

-- Handbook remediation: each background calendar row carries a distinct conflict, status, and planning consequence.
UPDATE events
SET description =
    CASE (CAST(substr(event_id, -4) AS INTEGER) % 15)
      WHEN 0 THEN 'background note，background notetrainingbackground note。' WHEN 1 THEN 'background note，background note。'
      WHEN 2 THEN 'background note，background notesleepbackground notetraining。' WHEN 3 THEN 'Family matterbackground noteconfirmation，background note。'
      WHEN 4 THEN 'Low-impact activitybackground note，background notefatiguebackground note。' WHEN 5 THEN 'Fitness maintenancebackground note，background notesleepbackground notedeload。'
      WHEN 6 THEN 'Uniform and luggage organization uses standing time; preserve hydration.' WHEN 7 THEN 'background note，background note。'
      WHEN 8 THEN 'background note，Locationbackground noteupdateCommutebackground note。' WHEN 9 THEN 'background note，background notetrainingbackground note。'
      WHEN 10 THEN 'background note，background note。' WHEN 11 THEN 'background note，background notecompanyauthorizationbackground notehealthbackground note。'
      WHEN 12 THEN 'background note，background note。' WHEN 13 THEN 'background notemaintain，background note。'
      ELSE 'background note，background note。' END
    || ' '
    || CASE CAST((CAST(substr(event_id, -4) AS INTEGER) - 1) / 15 AS INTEGER)
      WHEN 0 THEN 'background noterecordbackground noteconfirmation，background note。' WHEN 1 THEN 'background noterecordbackground note，background note。'
      WHEN 2 THEN 'background noterecordbackground note，background notereview。' WHEN 3 THEN 'background noterecordbackground note，background noteplan。'
      WHEN 4 THEN 'Locationbackground noteairportbackground note，background note。' WHEN 5 THEN 'Locationbackground note，background note。'
      WHEN 6 THEN 'Locationbackground note，background note。' WHEN 7 THEN 'background notesleepbackground note。'
      WHEN 8 THEN 'background note、background note。' WHEN 9 THEN 'background note，background note。'
      WHEN 10 THEN 'background noteweatherbackground note。' WHEN 11 THEN 'background notestockbackground noteequipmentbackground note，background notepurchase。'
      WHEN 12 THEN 'background notepainbackground note，background note。' WHEN 13 THEN 'background notecompanybackground notecyclebackground notehealthbackground note。'
      ELSE 'reviewbackground note、background notetrainingbackground note。' END
    || ' Location=' || COALESCE(location, 'background note') || '；background note=' || start_dt || 'background note' || end_dt || '；status=' || status || '。'
WHERE event_id LIKE 'cal_bg_%'
  AND event_id NOT BETWEEN 'cal_bg_0151' AND 'cal_bg_0210';

-- Stage-0 isolation: the flight roster is delivered by the later email
-- mutation, and generic background rows must not expose September facts before
-- the 2026-09-01 09:00 kickoff. Keep the distractor volume, but place these
-- rows in August where they are historical and harmless.
DELETE FROM events
WHERE event_id IN (
  'cal_flight_pvg_cdg_0907', 'cal_flight_cdg_pvg_0910',
  'cal_flight_pvg_jfk_0918', 'cal_flight_jfk_pvg_0921',
  'cal_flight_pvg_sin_1001', 'cal_flight_sin_pvg_1002'
);
UPDATE events
SET start_dt = printf('2026-08-%02dT%02d:00:00+08:00',
                      1 + ((CAST(substr(event_id, -4) AS INTEGER) - 63) % 28),
                      7 + (CAST(substr(event_id, -4) AS INTEGER) % 10)),
    end_dt = printf('2026-08-%02dT%02d:00:00+08:00',
                    1 + ((CAST(substr(event_id, -4) AS INTEGER) - 63) % 28),
                    8 + (CAST(substr(event_id, -4) AS INTEGER) % 10)),
    updated_at = '2026-08-31T18:00:00+08:00'
WHERE event_id BETWEEN 'cal_bg_0063' AND 'cal_bg_0150';
UPDATE events
SET summary = 'Historical calendar item ' || event_id,
    description = 'Historical personal calendar commitment; coordinate training around this item.',
    location = COALESCE(location, 'Shanghai')
WHERE event_id BETWEEN 'cal_bg_0063' AND 'cal_bg_0150';
